var i=`zero-trust-architecture`;var r=73;var s={en:[{id:`T073-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Zero Trust Architecture`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A Secure SDLC integrates security decisions and verification throughout planning, design, implementation, delivery and operations.`},{id:`B`,text:`Zero Trust treats network location as insufficient proof of trust and requires explicit identity, device/workload context and policy for access decisions.`},{id:`C`,text:`Defense in Depth uses multiple independent security controls so a single error or compromise does not expose the entire system.`},{id:`D`,text:`Cryptography protects information and proves authenticity using well-studied primitives: symmetric encryption, public-key cryptography, cryptographic hashes, MACs and digital signatures.`}]},{id:`T073-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Zero Trust Architecture`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Draw data flows, actors, trust boundaries and stores.`},{id:`B`,text:`The 2025 categories also cover authentication, software/data integrity, logging and alerting, and mishandling exceptional conditions.`},{id:`C`,text:`Authenticate and authorize every meaningful access path, segment resources and continuously evaluate risk signals.`},{id:`D`,text:`Scope access by resource, action, tenant and environment.`}]},{id:`T073-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Sensitive actions may require additional assurance.`},{id:`B`,text:`Threats include forged callbacks, replay, payload tampering and resource exhaustion; mitigations include signature checks, event IDs and limits.`},{id:`C`,text:`For a multi-tenant booking API, test broken object-level access using another tenant's reservation ID; test injection at search filters and verify secrets are absent from error responses.`},{id:`D`,text:`An API signs webhook messages with a keyed MAC so recipients detect tampering, while passwords are stored using Argon2id or another appropriate password hashing function, never reversible encryption.`}]},{id:`T073-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Zero Trust Architecture`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`No tool catches every logic bug; noisy scanners need triage.`},{id:`B`,text:`Zero Trust does not mean reauthenticating human users on every click.`},{id:`C`,text:`An absence of known CVEs does not prove a package safe; typosquatting and maintainer compromise are different threats.`},{id:`D`,text:`A threat model becomes stale as integration paths change.`}]},{id:`T073-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It is a design approach, not one product or perimeter rule.`}]}]},{id:`T073-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Zero Trust means blocking every internal request regardless of identity.`}]}]},{id:`T073-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Incomplete asset inventory or inconsistent policy enforcement can create blind spots and outages.`}]}]},{id:`T073-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Zero Trust Architecture`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Security reviews should begin only after software reaches production.`},{id:`B`,text:`Zero Trust treats network location as insufficient proof of trust and requires explicit identity, device/workload context and policy for access decisions.`},{id:`C`,text:`Any request from a private subnet should bypass authentication in Zero Trust.`},{id:`D`,text:`Authenticate and authorize every meaningful access path, segment resources and continuously evaluate risk signals.`}]},{id:`T073-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Zero Trust Architecture`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Threat modeling should list only bugs already observed in production.`},{id:`B`,text:`Sensitive actions may require additional assurance.`},{id:`C`,text:`Incomplete asset inventory or inconsistent policy enforcement can create blind spots and outages.`},{id:`D`,text:`Zero Trust means blocking every internal request regardless of identity.`}]},{id:`T073-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to map trust boundaries across frontend, API, worker and database. Require a policy enforcement point and failure behavior for missing identity claims.`},{id:`B`,text:`Ask an agent to audit a package update PR, explain provenance, lockfile changes, install scripts, CI permissions and a safe rollout path.`},{id:`C`,text:`Ask an agent for a STRIDE analysis of payment callbacks including a data-flow diagram description, abuse cases, prioritized controls and security acceptance tests.`},{id:`D`,text:`Ask an agent to produce an SSDLC checklist for a new upload feature, assigning evidence and owners to requirements, code review, deployment and monitoring stages.`}]},{id:`T073-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which internal network request currently succeeds without an authorization decision?`}]}]},{id:`T073-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Zero Trust Architecture`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T073-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN.`,b:!0},{t:` — propose three checks for `},{t:`Zero Trust Architecture`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T073-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T073-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Zero Trust Architecture`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T073-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Архітектура Zero Trust`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Secure SDLC інтегрує безпеку в планування, архітектуру, реалізацію, випуск та експлуатацію.`},{id:`B`,text:`Zero Trust не вважає розташування в мережі достатнім доказом довіри й вимагає ідентичності, контексту пристрою/навантаження та політики доступу.`},{id:`C`,text:`Багаторівневий захист застосовує кілька незалежних контролів, щоб одна помилка чи злам не відкривали всю систему.`},{id:`D`,text:`Криптографія захищає дані та підтверджує автентичність через вивчені примітиви: симетричне й асиметричне шифрування, хеші, MAC та цифрові підписи.`}]},{id:`T073-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Архітектура Zero Trust`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Намалюйте потоки даних, учасників, межі довіри й сховища.`},{id:`B`,text:`Інші категорії 2025 охоплюють автентифікацію, цілісність програм і даних, логування та оповіщення, а також неправильну обробку виняткових ситуацій.`},{id:`C`,text:`Автентифікуйте й авторизуйте кожен значущий доступ, сегментуйте ресурси та переоцінюйте ризики.`},{id:`D`,text:`Обмежуйте доступ за ресурсом, дією, tenant і середовищем.`}]},{id:`T073-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Для чутливих дій може бути потрібне додаткове підтвердження.`},{id:`B`,text:`Загрози: підроблений callback, replay, зміна payload та виснаження ресурсів; захисти: підписи, ID подій і ліміти.`},{id:`C`,text:`Для мультитенантного API бронювань перевіряйте доступ до ID чужої броні, injection у фільтрах і відсутність секретів у повідомленнях про помилки.`},{id:`D`,text:`API підписує webhook через keyed MAC для виявлення змін, а паролі зберігає через Argon2id чи інший придатний password hashing, а не зворотне шифрування.`}]},{id:`T073-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Архітектура Zero Trust`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Жоден інструмент не ловить усі логічні помилки; шум сканерів потребує triage.`},{id:`B`,text:`Zero Trust не означає повторний логін людини після кожного кліку.`},{id:`C`,text:`Відсутність відомих CVE не доводить безпеку пакета; typosquatting і захоплення акаунта maintainer — інші загрози.`},{id:`D`,text:`Модель загроз старіє після змін інтеграцій.`}]},{id:`T073-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Це підхід, а не один продукт чи firewall.`}]}]},{id:`T073-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Zero Trust означає блокувати кожен внутрішній запит незалежно від ідентичності.`}]}]},{id:`T073-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Неповний інвентар ресурсів та неоднакове застосування політик створюють прогалини й збої.`}]}]},{id:`T073-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Архітектура Zero Trust`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Перевірки безпеки слід починати лише після виходу ПЗ у продакшн.`},{id:`B`,text:`Zero Trust не вважає розташування в мережі достатнім доказом довіри й вимагає ідентичності, контексту пристрою/навантаження та політики доступу.`},{id:`C`,text:`Будь-який запит із приватної підмережі має обходити автентифікацію в Zero Trust.`},{id:`D`,text:`Автентифікуйте й авторизуйте кожен значущий доступ, сегментуйте ресурси та переоцінюйте ризики.`}]},{id:`T073-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Архітектура Zero Trust`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Моделювання загроз має перелічувати лише баги, вже помічені в продакшні.`},{id:`B`,text:`Для чутливих дій може бути потрібне додаткове підтвердження.`},{id:`C`,text:`Неповний інвентар ресурсів та неоднакове застосування політик створюють прогалини й збої.`},{id:`D`,text:`Zero Trust означає блокувати кожен внутрішній запит незалежно від ідентичності.`}]},{id:`T073-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента намалювати межі довіри між фронтендом, API, воркером та БД. Вимагайте точки застосування політики й поведінку за відсутніх identity claims.`},{id:`B`,text:`Попросіть агента перевірити PR з оновленням пакетів: походження, зміни lockfile, install scripts, права CI й безпечний rollout.`},{id:`C`,text:`Попросіть агента провести STRIDE-аналіз платіжних callback із описом потоків, сценаріями зловживань, пріоритетними захистами та приймальними тестами безпеки.`},{id:`D`,text:`Попросіть агента створити SSDLC-чекліст для upload з доказами й відповідальними на етапах вимог, review, деплою та моніторингу.`}]},{id:`T073-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Який запит із внутрішньої мережі зараз проходить без окремого рішення авторизації?`}]}]},{id:`T073-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Архітектура Zero Trust`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T073-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Архітектура Zero Trust`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T073-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T073-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Архітектура Zero Trust`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:73,questions:s};export{n as default,s as questions,i as slug,r as topicId};